css:
/* ============ 基线 ============ */
*,*::before,*::after{box-sizing:border-box}
:root{
  --paper:#FBF9F5; --paper-2:#F3EFE7; --card:#FFFFFF;
  --ink:#2A211B; --ink-2:#5F5348; --ink-3:#8A7E70;
  --line:rgba(42,33,27,.13); --line-2:rgba(42,33,27,.26);
  --clay:#C0442A; --clay-soft:#FAEDE8; --clay-dark:#9B331E;
  --focus:#1F5FA8;
  --r:8px; --r-tag:4px;
  --ease:cubic-bezier(.16,1,.3,1);
  --s2:8px;--s3:12px;--s4:16px;--s5:20px;--s6:24px;--s8:32px;--s10:40px;--s12:48px;--s16:64px;--s20:80px;
}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;background:var(--paper);color:var(--ink);
  font-family:"PingFang SC","Hiragino Sans GB","Noto Sans SC","Microsoft YaHei",-apple-system,sans-serif;
  font-size:16px;line-height:1.62;
  background-image:radial-gradient(rgba(42,33,27,.035) 1px,transparent 1px);
  background-size:22px 22px;
}
h1,h2,h3,h4,p,dl,dd,dt,figure{margin:0}
ul{margin:0;padding:0;list-style:none}
a{color:inherit}
button{font:inherit;color:inherit}
.mono{font-family:"SF Mono",ui-monospace,"JetBrains Mono",Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.wrap{width:100%;max-width:1200px;margin:0 auto;padding:0 var(--s5)}
:where(a,button,[tabindex]):focus-visible{outline:3px solid var(--focus);outline-offset:2px;border-radius:2px}
.skip{position:absolute;left:var(--s3);top:-60px;background:var(--ink);color:var(--paper);padding:10px 16px;border-radius:var(--r);z-index:60;font-size:14px}
.skip:focus{top:var(--s3)}

/* ============ 报头 ============ */
.masthead{position:sticky;top:0;z-index:30;background:rgba(251,249,245,.93);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.masthead__inner{display:flex;align-items:center;gap:var(--s5);min-height:64px}
.masthead__brand{display:flex;align-items:baseline;gap:var(--s2)}
.wordmark{font-size:22px;font-weight:700;letter-spacing:.14em}
.wordmark__latin{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:11px;letter-spacing:.22em;color:var(--ink-3)}
.masthead__nav{display:flex;gap:var(--s6);margin-left:auto}
.masthead__nav a{font-size:14px;text-decoration:none;color:var(--ink-2);padding:6px 2px;border-bottom:1px solid transparent;transition:color .18s var(--ease),border-color .18s var(--ease)}
.masthead__nav a:hover{color:var(--ink);border-bottom-color:var(--clay)}
.bagbtn{display:flex;align-items:center;gap:var(--s2);min-height:44px;padding:0 var(--s4);background:var(--ink);color:var(--paper);border:1px solid var(--ink);border-radius:var(--r);cursor:pointer;font-size:14px;font-weight:600;transition:background .18s var(--ease)}
.bagbtn:hover{background:#3B2F26}
.bagbtn__count{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:12px;background:var(--paper);color:var(--ink);border-radius:var(--r-tag);padding:1px 6px;min-width:22px;text-align:center}
.bagbtn.has-items .bagbtn__count{background:var(--clay);color:#fff}

/* ============ 引言 ============ */
.intro{padding:var(--s16) 0 var(--s12)}
.eyebrow{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:12px;letter-spacing:.16em;color:var(--ink-3)}
.intro__title{margin:var(--s5) 0 0;font-size:clamp(34px,5.6vw,68px);font-weight:700;line-height:1.12;letter-spacing:.01em}
.intro__accent{color:var(--clay)}
.intro__cols{margin-top:var(--s8);display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:var(--s10);align-items:start;border-top:1px solid var(--line);padding-top:var(--s6)}
.intro__lede{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:17px;line-height:1.78;color:var(--ink-2);max-width:34em}
.intro__facts{display:flex;flex-direction:column;gap:var(--s3)}
.intro__facts>div{display:flex;justify-content:space-between;gap:var(--s4);border-bottom:1px solid var(--line);padding-bottom:var(--s3);font-size:14px}
.intro__facts dt{color:var(--ink-3)}
.intro__facts dd{text-align:right}
.intro__facts em{font-style:normal;color:var(--ink-3);font-size:12px}

/* ============ 特色区 7:3 ============ */
.feature{padding-bottom:var(--s16)}
.feature__grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,3fr);gap:var(--s10);align-items:start}
.plate{position:relative;background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;display:flex;align-items:center;justify-content:center}
.plate::after{content:"";position:absolute;inset:0;background:linear-gradient(160deg,rgba(255,255,255,.7),rgba(255,255,255,0) 58%);pointer-events:none}
.plate svg{display:block;width:100%;height:auto;position:relative;z-index:1}
.plate--hero{aspect-ratio:5/4;padding:var(--s8)}
.feature__cap{margin-top:var(--s3);font-size:13px;color:var(--ink-3);display:flex;gap:var(--s3);flex-wrap:wrap}
.feature__side{padding-top:var(--s2)}
.feature__title{font-size:clamp(26px,3vw,34px);font-weight:700;line-height:1.2;margin:var(--s3) 0 var(--s4)}
.feature__desc{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:16px;line-height:1.78;color:var(--ink-2)}
.speclist{margin-top:var(--s6);border-top:1px solid var(--line)}
.speclist__row{display:flex;justify-content:space-between;gap:var(--s4);padding:var(--s3) 0;border-bottom:1px solid var(--line);font-size:14px}
.speclist__row dt{color:var(--ink-3)}
.speclist__row dd{text-align:right;font-weight:500}

/* ============ 目录 ============ */
.section__title{font-size:clamp(24px,2.6vw,32px);font-weight:700;line-height:1.22}
.section__sub{font-size:14px;color:var(--ink-3);margin-top:var(--s2);max-width:44em}
.catalog{padding-bottom:var(--s20)}
.catalog__head{display:flex;flex-wrap:wrap;gap:var(--s5);justify-content:space-between;align-items:flex-end;border-top:2px solid var(--ink);padding-top:var(--s6)}
.filters{display:flex;flex-wrap:wrap;gap:var(--s2)}
.chip{min-height:44px;padding:0 var(--s5);background:transparent;border:1px solid var(--line-2);border-radius:var(--r-tag);cursor:pointer;font-size:14px;color:var(--ink-2);transition:background .18s var(--ease),color .18s var(--ease),border-color .18s var(--ease)}
.chip:hover{background:var(--paper-2);color:var(--ink)}
.chip[aria-pressed="true"]{background:var(--ink);border-color:var(--ink);color:var(--paper);font-weight:600}
.catalog__live{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:12px;color:var(--ink-3);margin:var(--s4) 0 var(--s6)}
.catalog__note{font-size:14px;color:var(--ink-2);border:1px dashed var(--line-2);border-radius:var(--r);padding:var(--s8);text-align:center}
.linkbtn{background:none;border:0;padding:8px;color:var(--clay-dark);text-decoration:underline;cursor:pointer;font-size:14px}

/* 非等宽网格：尺度分级 */
.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:var(--s8) var(--s6)}
.card{grid-column:span 2;display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;transition:border-color .22s var(--ease),transform .22s var(--ease)}
.card:hover{border-color:var(--line-2);transform:translateY(-2px)}
.card[data-w="2"]{grid-column:span 4}
.card.is-active{border-color:var(--clay)}
.card__plate{background:var(--paper-2);border-bottom:1px solid var(--line);aspect-ratio:4/3;padding:var(--s5)}
.card__plate svg{width:70%;height:auto;margin:auto}
.card[data-w="2"] .card__plate{aspect-ratio:21/9}
.card__body{padding:var(--s5);display:flex;flex-direction:column;gap:var(--s3);flex:1}
.card[data-w="2"] .card__body{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);grid-template-areas:"hd hd" "sp mt" "sp ac" "sp ac";gap:var(--s4) var(--s8)}
.card[data-w="2"] .card__head{grid-area:hd}
.card[data-w="2"] .card__spec{grid-area:sp}
.card[data-w="2"] .card__meta{grid-area:mt;margin-top:0}
.card[data-w="2"] .card__actions{grid-area:ac;align-self:start}
.card__head{display:flex;justify-content:space-between;align-items:baseline;gap:var(--s3)}
.card__name{font-size:19px;font-weight:700;line-height:1.3}
.card__id{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:12px;color:var(--ink-3);white-space:nowrap}
.card__spec{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:14px;line-height:1.74;color:var(--ink-2)}
.card__tags{display:flex;flex-wrap:wrap;gap:var(--s2);margin-top:var(--s3)}
.tag{font-size:12px;border:1px solid var(--line);border-radius:var(--r-tag);padding:2px 8px;color:var(--ink-2);background:var(--paper)}
.card__meta{display:flex;flex-direction:column;gap:var(--s2);border-top:1px solid var(--line);padding-top:var(--s3);margin-top:auto}
.card__metaRow{display:flex;justify-content:space-between;gap:var(--s4);font-size:13px}
.card__metaRow dt{color:var(--ink-3)}
.card__metaRow dd{text-align:right}
.card__actions{display:flex;flex-wrap:wrap;gap:var(--s3);align-items:center;border-top:1px solid var(--line);padding-top:var(--s4)}
.price{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:22px;font-weight:600;color:var(--clay);margin-right:auto;white-space:nowrap}
.price small{font-size:12px;font-weight:400;color:var(--ink-3);margin-left:6px}
.btn{min-height:44px;padding:0 var(--s5);border-radius:var(--r);cursor:pointer;font-size:14px;font-weight:600;border:1px solid transparent;transition:background .2s var(--ease),color .2s var(--ease),border-color .2s var(--ease)}
.btn--primary{background:var(--clay);color:#fff;border-color:var(--clay)}
.btn--primary:hover{background:var(--clay-dark);border-color:var(--clay-dark)}
.btn--ghost{background:transparent;border-color:var(--line-2);color:var(--ink)}
.btn--ghost:hover{background:var(--paper-2)}
.btn--done{background:var(--ink);color:var(--paper);border-color:var(--ink)}
.specbtn{background:transparent;border:1px solid var(--line-2);color:var(--ink-2)}
.specbtn:hover{background:var(--paper-2)}
.specbtn[aria-expanded="true"]{border-color:var(--ink);color:var(--ink);background:var(--paper-2)}
.icon{width:16px;height:16px;display:inline-block;vertical-align:-2px;margin-right:6px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}

/* 原位展开规格 */
.specPanel{grid-column:1/-1;border-top:1px dashed var(--line-2);margin-top:var(--s4);padding-top:var(--s4);display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:var(--s3) var(--s6)}
.specPanel[hidden]{display:none}
.specPanel>div{display:flex;flex-direction:column;gap:2px;font-size:13px}
.specPanel dt{color:var(--ink-3)}
.specPanel dd{margin:0;font-weight:500}

/* ============ 材料 ============ */
.materials{border-top:1px solid var(--line);background:var(--paper-2);padding:var(--s16) 0}
.mat__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--s8);margin-top:var(--s8)}
.mat{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:var(--s6);display:flex;flex-direction:column;gap:var(--s3)}
.mat__name{font-size:18px;font-weight:700;display:flex;align-items:center;gap:var(--s2)}
.mat__name::before{content:"✦";color:var(--clay);font-size:13px}
.mat__body{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:15px;line-height:1.78;color:var(--ink-2)}
.mat__care{font-size:13px;color:var(--ink-3);border-top:1px solid var(--line);padding-top:var(--s3);margin-top:auto}

/* ============ 关于 / 页脚 ============ */
.about{padding:var(--s16) 0}
.about__body{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:17px;line-height:1.78;color:var(--ink-2);max-width:38em;margin-top:var(--s4)}
.about__note{margin-top:var(--s5);font-size:13px;line-height:1.7;color:var(--ink-3);border:1px solid var(--line);border-radius:var(--r);padding:var(--s4);max-width:60em;background:var(--paper-2)}
.foot{border-top:1px solid var(--line);padding:var(--s8) 0}
.foot__inner{display:flex;flex-wrap:wrap;gap:var(--s3) var(--s8);justify-content:space-between;align-items:baseline}
.foot__brand{font-size:14px;font-weight:600}
.foot__meta{font-size:12px;color:var(--ink-3)}

/* ============ 购物袋 ============ */
.bag{position:fixed;inset:0;z-index:50;display:flex;justify-content:flex-end}
.bag[hidden]{display:none}
.bag__backdrop{position:absolute;inset:0;background:rgba(42,33,27,.34)}
.bag__sheet{position:relative;width:min(420px,100%);height:100%;background:var(--paper);border-left:1px solid var(--line-2);display:flex;flex-direction:column;overflow-y:auto;animation:slideIn .34s var(--ease)}
@keyframes slideIn{from{transform:translateX(16px);opacity:.5}to{transform:translateX(0);opacity:1}}
.bag__head{display:flex;justify-content:space-between;align-items:center;padding:var(--s5);border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--paper);z-index:2}
.bag__title{font-size:19px;font-weight:700}
.bag__close{min-height:44px;padding:0 var(--s3);background:none;border:1px solid var(--line-2);border-radius:var(--r);cursor:pointer;font-size:13px;color:var(--ink-2)}
.bag__close:hover{background:var(--paper-2)}
.bag__demo{margin:var(--s5) var(--s5) 0;font-size:12px;line-height:1.68;color:var(--clay-dark);background:var(--clay-soft);border:1px solid rgba(192,68,42,.32);border-radius:var(--r);padding:var(--s3) var(--s4)}
.bag__empty{padding:var(--s10) var(--s5);text-align:center;display:flex;flex-direction:column;gap:var(--s3);align-items:center}
.bag__emptyTitle{font-size:17px;font-weight:700}
.bag__emptyBody{font-family:"Songti SC","Noto Serif SC",Georgia,serif;font-size:15px;line-height:1.72;color:var(--ink-2)}
.bag__list{padding:var(--s4) var(--s5);display:flex;flex-direction:column}
.bag__item{display:grid;grid-template-columns:64px minmax(0,1fr);gap:var(--s4);padding:var(--s4) 0;border-bottom:1px solid var(--line)}
.bag__thumb{width:64px;height:64px;background:var(--paper-2);border:1px solid var(--line);border-radius:var(--r-tag);overflow:hidden}
.bag__thumb svg{width:100%;height:100%;display:block}
.bag__itemName{font-size:15px;font-weight:600;line-height:1.35}
.bag__itemSku{font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:12px;color:var(--ink-3)}
.bag__itemRow{display:flex;align-items:center;gap:var(--s3);margin-top:var(--s2);flex-wrap:wrap}
.qty{display:flex;align-items:center;border:1px solid var(--line-2);border-radius:var(--r-tag);overflow:hidden}
.qty button{width:44px;height:44px;background:transparent;border:0;cursor:pointer;font-size:17px;line-height:1;color:var(--ink)}
.qty button:hover{background:var(--paper-2)}
.qty span{min-width:34px;text-align:center;font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:14px}
.bag__lineTotal{margin-left:auto;font-family:"SF Mono",ui-monospace,Menlo,monospace;font-size:15px;font-weight:600;color:var(--clay)}
.bag__del{background:none;border:0;padding:10px 0;font-size:13px;color:var(--ink-3);text-decoration:underline;cursor:pointer;min-height:44px}
.bag__del:hover{color:var(--clay-dark)}
.bag__foot{margin-top:auto;padding:var(--s5);border-top:1px solid var(--line);position:sticky;bottom:0;background:var(--paper)}
.bag__totalRow{display:flex;justify-content:space-between;align-items:baseline;font-size:15px}
.bag__totalRow strong{font-size:26px;color:var(--clay)}
.bag__footNote{font-size:12px;color:var(--ink-3);margin-top:var(--s2)}
.bag__clear{margin-top:var(--s4);width:100%}

/* ============ 响应式 ============ */
@media (max-width:1023px){
  .feature__grid{grid-template-columns:1fr;gap:var(--s8)}
  .plate--hero{aspect-ratio:3/2}
  .mat__grid{grid-template-columns:1fr 1fr}
  .grid{grid-template-columns:repeat(4,1fr)}
  .card,.card[data-w="2"]{grid-column:span 2}
  .card[data-w="2"] .card__body{display:flex}
  .card[data-w="2"] .card__plate{aspect-ratio:4/3}
}
@media (max-width:767px){
  .masthead__nav{display:none}
  .masthead__inner{gap:var(--s3)}
  .bagbtn{margin-left:auto}
  .intro{padding-top:var(--s12)}
  .intro__cols{grid-template-columns:1fr;gap:var(--s6)}
  .grid{grid-template-columns:1fr;gap:var(--s6)}
  .card,.card[data-w="2"]{grid-column:span 1}
  .mat__grid{grid-template-columns:1fr}
  .catalog__head{align-items:flex-start;flex-direction:column}
  .filters{width:100%}
  .chip{flex:1 1 auto}
  .bag__sheet{width:100%;border-left:0}
  .materials,.about{padding-top:var(--s12);padding-bottom:var(--s12)}
  .card__plate svg{width:76%}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms !important;transition-duration:.01ms !important}
}

