  /* ---------- 数据与状态 ---------- */
  var PRODUCTS = JSON.parse(document.getElementById("productData").textContent);
  var BY_ID = {};
  PRODUCTS.forEach(function(p){ BY_ID[p.id] = p; });

  var state = { filter: "all", bag: [], open: null };

  function money(n){ return "¥" + n; }
  function el(tag, cls, text){
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function plate(cls, art){
    var d = el("div", cls);
    d.innerHTML = SVGS[art] || "";
    return d;
  }
  function bagQty(id){
    var line = state.bag.filter(function(l){ return l.id === id; })[0];
    return line ? line.qty : 0;
  }
  function bagTotalCount(){
    return state.bag.reduce(function(s, l){ return s + l.qty; }, 0);
  }
  function filterLabel(f){
    return { all: "全部", clay: "陶", wares: "器皿", textile: "织物" }[f] || f;
  }

  /* 首屏静态图位：把内联 SVG 注入标记为 data-art 的容器 */
  document.querySelectorAll("[data-art]").forEach(function(node){
    node.innerHTML = SVGS[node.dataset.art] || "";
  });

  /* ---------- 目录渲染 ---------- */
  var grid = document.getElementById("grid");
  var gridEmpty = document.getElementById("gridEmpty");
  var live = document.getElementById("catalogLive");

  function setAddLabel(btn, id){
    if (!btn || btn.dataset.morph === "1") return;
    btn.classList.toggle("btn--done", bagQty(id) > 0);
    btn.innerHTML = '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8h14l-1.2 11H6.2Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg>加入购物袋';
  }

  function renderGrid(){
    var list = PRODUCTS.filter(function(p){
      return state.filter === "all" || p.cat === state.filter;
    });
    grid.innerHTML = "";
    gridEmpty.hidden = list.length !== 0;

    list.forEach(function(p){
      var card = el("article", "card");
      card.dataset.w = String(p.w);
      card.dataset.id = p.id;
      if (state.open === p.id) card.classList.add("is-active");

      card.appendChild(plate("plate card__plate", p.art));

      var body = el("div", "card__body");

      var head = el("div", "card__head");
      head.appendChild(el("h3", "card__name", p.name));
      head.appendChild(el("span", "card__id", p.id));
      body.appendChild(head);

      var spec = el("div", "card__spec");
      spec.appendChild(el("p", null, p.spec));
      var tags = el("div", "card__tags");
      tags.appendChild(el("span", "tag", p.catLabel));
      tags.appendChild(el("span", "tag", p.use.split("。")[0].split("、")[0] + " 适用"));
      spec.appendChild(tags);
      body.appendChild(spec);

      var meta = el("dl", "card__meta");
      [["外形", p.details[1][1]], ["烧成 / 材质", p.details[2][1]]].forEach(function(row){
        var r = el("div", "card__metaRow");
        r.appendChild(el("dt", null, row[0]));
        r.appendChild(el("dd", "mono", row[1]));
        meta.appendChild(r);
      });
      body.appendChild(meta);

      var actions = el("div", "card__actions");
      var price = el("p", "price");
      price.appendChild(document.createTextNode(money(p.price)));
      price.appendChild(el("small", null, "概念价 · 演示"));
      actions.appendChild(price);

      var specBtn = el("button", "btn specbtn");
      specBtn.type = "button";
      specBtn.setAttribute("aria-expanded", state.open === p.id ? "true" : "false");
      specBtn.setAttribute("aria-controls", "spec-" + p.id);
      specBtn.innerHTML = '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h10"/></svg>规格';
      specBtn.addEventListener("click", function(){
        var willOpen = state.open !== p.id;
        state.open = willOpen ? p.id : null;
        renderGrid();
        if (willOpen){
          var btn = grid.querySelector('[data-id="' + p.id + '"] .specbtn');
          if (btn) btn.focus();
        }
      });
      actions.appendChild(specBtn);

      var addBtn = el("button", "btn btn--primary");
      addBtn.type = "button";
      setAddLabel(addBtn, p.id);
      addBtn.addEventListener("click", function(){ addToBag(p.id, addBtn); });
      actions.appendChild(addBtn);

      body.appendChild(actions);

      var panel = el("dl", "specPanel");
      panel.id = "spec-" + p.id;
      if (state.open !== p.id) panel.hidden = true;
      p.details.concat([["用途", p.use]]).forEach(function(d){
        var w = el("div");
        w.appendChild(el("dt", null, d[0]));
        w.appendChild(el("dd", "mono", d[1]));
        panel.appendChild(w);
      });
      body.appendChild(panel);

      card.appendChild(body);
      grid.appendChild(card);
    });

    live.textContent = state.filter === "all"
      ? "显示全部 " + PRODUCTS.length + " 件"
      : "「" + filterLabel(state.filter) + "」有 " + list.length + " 件 · 全辑共 " + PRODUCTS.length + " 件";
  }

  /* 微创新 M2：加购按钮原位平滑变形，1.8s 后收回，不弹成功窗 */
  function morphAdd(btn, id){
    btn.dataset.morph = "1";
    btn.classList.add("btn--done");
    btn.innerHTML = '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>已入袋 · ' + bagQty(id) + " 件";
    window.setTimeout(function(){
      delete btn.dataset.morph;
      btn.classList.remove("btn--done");
      setAddLabel(btn, id);
    }, 1800);
  }

  /* ---------- 筛选 ---------- */
  document.querySelectorAll(".chip").forEach(function(chip){
    chip.addEventListener("click", function(){
      state.filter = chip.dataset.filter;
      document.querySelectorAll(".chip").forEach(function(c){
        var on = c === chip;
        c.setAttribute("aria-pressed", on ? "true" : "false");
        c.classList.toggle("is-on", on);
      });
      renderGrid();
    });
  });
  gridEmpty.querySelector("[data-filter]").addEventListener("click", function(){
    document.querySelector('.chip[data-filter="all"]').click();
  });

  /* ---------- 购物袋 ---------- */
  var bagPanel = document.getElementById("bagPanel");
  var bagList = document.getElementById("bagList");
  var bagEmpty = document.getElementById("bagEmpty");
  var bagFoot = document.getElementById("bagFoot");
  var bagBtn = document.getElementById("bagBtn");
  var lastFocus = null;

  function setBagOpen(open){
    bagPanel.hidden = !open;
    bagBtn.setAttribute("aria-expanded", open ? "true" : "false");
    if (open){
      lastFocus = document.activeElement;
      document.getElementById("bagClose").focus();
    } else if (lastFocus && document.contains(lastFocus)){
      lastFocus.focus();
    } else {
      bagBtn.focus();
    }
  }
  bagBtn.addEventListener("click", function(){ setBagOpen(bagPanel.hidden); });
  document.getElementById("bagClose").addEventListener("click", function(){ setBagOpen(false); });
  document.getElementById("bagBackdrop").addEventListener("click", function(){ setBagOpen(false); });
  document.addEventListener("keydown", function(e){
    if (e.key === "Escape" && !bagPanel.hidden) setBagOpen(false);
  });
  document.getElementById("bagEmptyCta").addEventListener("click", function(){
    setBagOpen(false);
    document.getElementById("catalog").scrollIntoView({ behavior: "smooth", block: "start" });
  });
  document.getElementById("bagClear").addEventListener("click", function(){
    state.bag = [];
    renderBag();
    renderGrid();
  });

  function addToBag(id, btn){
    var line = state.bag.filter(function(l){ return l.id === id; })[0];
    if (line) line.qty += 1; else state.bag.push({ id: id, qty: 1 });
    renderBag();
    if (btn) morphAdd(btn, id);
  }
  function setQty(id, delta){
    state.bag.forEach(function(l){ if (l.id === id) l.qty += delta; });
    state.bag = state.bag.filter(function(l){ return l.qty > 0; });
    renderBag();
    renderGrid();
  }
  function removeLine(id){
    state.bag = state.bag.filter(function(l){ return l.id !== id; });
    renderBag();
    renderGrid();
  }

  function renderBag(){
    var count = bagTotalCount();
    document.getElementById("bagCount").textContent = String(count);
    document.getElementById("bagBtnSr").textContent = "购物袋，" + count + " 件";
    document.getElementById("bagHeadCount").textContent = "(" + count + ")";
    document.getElementById("bagFootCount").textContent = String(count);
    bagBtn.classList.toggle("has-items", count > 0);

    bagEmpty.hidden = count > 0;
    bagFoot.hidden = count === 0;
    bagList.innerHTML = "";

    var total = 0;
    state.bag.forEach(function(l){
      var p = BY_ID[l.id];
      total += p.price * l.qty;

      var li = el("li", "bag__item");
      li.appendChild(plate("bag__thumb", p.art));

      var info = el("div");
      info.appendChild(el("p", "bag__itemName", p.name));
      info.appendChild(el("p", "bag__itemSku", p.id + " · " + money(p.price)));

      var row = el("div", "bag__itemRow");
      var qty = el("div", "qty");
      var minus = el("button");
      minus.type = "button"; minus.textContent = "−";
      minus.setAttribute("aria-label", "减少「" + p.name + "」数量");
      minus.addEventListener("click", function(){ setQty(l.id, -1); });
      var num = el("span", null, String(l.qty));
      num.setAttribute("aria-label", "「" + p.name + "」数量 " + l.qty);
      var plus = el("button");
      plus.type = "button"; plus.textContent = "+";
      plus.setAttribute("aria-label", "增加「" + p.name + "」数量");
      plus.addEventListener("click", function(){ setQty(l.id, 1); });
      qty.appendChild(minus); qty.appendChild(num); qty.appendChild(plus);
      row.appendChild(qty);
      row.appendChild(el("span", "bag__lineTotal", money(p.price * l.qty)));
      info.appendChild(row);

      var del = el("button", "bag__del", "从袋中移除");
      del.type = "button";
      del.addEventListener("click", function(){ removeLine(l.id); });
      info.appendChild(del);

      li.appendChild(info);
      bagList.appendChild(li);
    });

    document.getElementById("bagTotal").textContent = money(total);
